import json,math
from pathlib import Path
from shapely.geometry import Polygon
root=Path(__file__).resolve().parents[1];b=next(b for b in json.loads((root/'public/data/buildings.json').read_text())['buildings'] if b['id']=='36402');p=Polygon([(x,-y) for x,y in b['ring']]);coords=list(p.minimum_rotated_rectangle.exterior.coords);a,c=max(zip(coords,coords[1:]),key=lambda e:math.dist(*e));dx,dy=c[0]-a[0],c[1]-a[1];l=math.hypot(dx,dy);u=(dx/l,dy/l);n=(-u[1],u[0]);center=(p.centroid.x,p.centroid.y);xs=[(x-center[0])*u[0]+(y-center[1])*u[1] for x,y in p.exterior.coords];ys=[(x-center[0])*n[0]+(y-center[1])*n[1] for x,y in p.exterior.coords];d={'source_section':b,'center':center,'axis':u,'normal':n,'length_bounds':[min(xs),max(xs)],'width_bounds':[min(ys),max(ys)],'reference':'https://collections.museumsvictoria.com.au/items/1396611','limits':'Museums Victoria documents three riveted iron girder arch spans and bluestone piers/abutments. Arch profiles, thickness, pier positions, six ribs per span and flat vertical datum authored within retained footprint and 9.5 m top; ornament/current restoration unresolved.'};(root/'assets/source/environment/princes-bridge-arches.json').write_text(json.dumps(d,indent=2)+'\n');print('VERIFIED bridge bounds',d['length_bounds'],d['width_bounds'])
